import random

from agent import agent_answer, make_tool


def coin_flip():
    return random.choice(["Орёл", "Решка"])


TOOLS = [make_tool("coin_flip", "Подбросить монетку: орёл или решка.")]
FUNCTIONS = {"coin_flip": lambda args: coin_flip()}

messages = [{"role": "user", "content": input("Ты: ")}]
print("Агент:", agent_answer(messages, TOOLS, FUNCTIONS))

TOOLS = [make_tool("roll_dice", "Бросить кубик.",
                   {"sides": {"type": "integer", "description": "Число граней"}})]
FUNCTIONS = {"roll_dice": lambda args: roll_dice(args.get("sides", 6))}

